-- Runner copy of server/src/db-draft/0009_child_records_inherit_tenant_scope.sql.
-- Generated by scripts/build-tenant-migration.mjs; edit the draft and regenerate, do not hand-edit
-- both. Differences from the draft: psql meta-commands removed, and BEGIN/COMMIT removed because
-- the migration runner applies every file inside its own transaction (and records the result in
-- schema_migrations). Semantics are otherwise identical.

-- =============================================================================
-- DHAROHAR — DRAFT migration 0009: a child record inherits its parcel's tenant
--
-- Why this migration exists
--
--   0006 put `parcels` and `land_documents` under row-level security. Everything else that belongs to
--   a tenant was left to the application layer — including the three tables that hold the most
--   intimate parts of a land record:
--
--     parcel_owners      the co-sharers: names, parent's name, share fractions
--     parcel_mutations   the history: what changed, when, who recorded it
--     field_inspections  the survey: who stood on the land, what they saw, the photo and its digest
--
--   Each of those rows carries a parcel_id and nothing else — no organization_id of its own. Their
--   tenant IS their parcel's tenant. The application has always read and written them through a
--   parcel the caller proved visible, so the HTTP surface was safe; but the runtime role can issue
--   SQL directly, and there the parent check did not exist: `SELECT * FROM parcel_owners WHERE
--   parcel_id = '…'` returned any tenant's co-sharers to any authenticated identity, with or without
--   a tenant context. The second layer stopped covering the payload the moment a record was split
--   across a parent and its children.
--
-- What this file does
--
--   Enables row-level security on the three child tables with one predicate, repeated for the four
--   commands: the row is visible/writable exactly when its PARENT PARCEL is visible to this tenant.
--   The subquery runs as dharohar_app, so 0006's policy on parcels applies inside it — the child does
--   not re-implement tenancy, it inherits it. There is no second copy of the rule to drift out of
--   agreement with the first.
--
--   Fail-closed properties, all of which the tenancy suite measures:
--     * no tenant context bound  -> the parent is invisible -> the child is invisible (0 rows)
--     * forged tenant context    -> the parent is invisible -> 0 rows
--     * parcel quarantined (organization_id IS NULL) -> the parcel is invisible to every tenant, so
--       its owners, mutations and inspections are too. Measured on the demo database before writing
--       this file: 12 of 42 parcel_owners rows hang off the 12 quarantined parcels, and 0 rows in
--       any of the three tables have a missing or NULL parent, so nothing that was reachable in the
--       application becomes unreachable here except through a parcel that is already unreachable.
--
--   Enabled, not FORCED, for the same reason as 0006: the schema owner has to migrate, seed and
--   diagnose, and that credential lives only in the one-shot services.
--
-- Running it
--
--   psql is used by the drill; the migration runner applies the derived copy of this file
--   (server/src/db/migrations/0009_…) inside its own transaction. Rollback: rollback-0009.sql.
-- =============================================================================


-- ---- 1. Guard: 0006's parent policy has to exist, or this protects nothing ---
DO $do$
DECLARE
  missing text;
BEGIN
  SELECT string_agg(t, ', ') INTO missing FROM unnest(ARRAY['parcels','land_documents']) t
   WHERE NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = t AND policyname = 'tenant_select_' || t);
  IF missing IS NOT NULL THEN
    RAISE EXCEPTION E'[TENANCY_PARENT_POLICY_MISSING] no tenant_select_ policy on: %.\n  0009 makes a child inherit its parent''s row-level policy. With no policy on the parent there is nothing to inherit, and enabling security on the child would filter by an unenforced rule.', missing
      USING HINT = 'Apply migration 0006 first.';
  END IF;
END
$do$;

-- ---- 2. Report what becomes unreachable, before doing it ---------------------
-- Printed first on purpose. An operator reading the log should see the consequence of the change
-- rather than discover it in a support ticket, and the drill asserts these numbers are what the
-- tables actually hold rather than trusting the comment above.
DO $do$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT 'parcel_owners'::text AS t, count(*)::text AS rows_,
           count(*) FILTER (WHERE p.id IS NULL)::text AS orphaned,
           count(*) FILTER (WHERE p.organization_id IS NULL)::text AS under_quarantine
      FROM parcel_owners o LEFT JOIN parcels p ON p.id = o.parcel_id
    UNION ALL
    SELECT 'parcel_mutations', count(*)::text,
           count(*) FILTER (WHERE p.id IS NULL)::text,
           count(*) FILTER (WHERE p.organization_id IS NULL)::text
      FROM parcel_mutations m LEFT JOIN parcels p ON p.id = m.parcel_id
    UNION ALL
    SELECT 'field_inspections', count(*)::text,
           count(*) FILTER (WHERE p.id IS NULL)::text,
           count(*) FILTER (WHERE p.organization_id IS NULL)::text
      FROM field_inspections i LEFT JOIN parcels p ON p.id = i.parcel_id
  LOOP
    RAISE NOTICE '[0009] %: rows=% parent-missing=% parent-quarantined=%', r.t, r.rows_, r.orphaned, r.under_quarantine;
  END LOOP;
END
$do$;

-- ---- 3. The policies --------------------------------------------------------
ALTER TABLE parcel_owners     ENABLE ROW LEVEL SECURITY;
ALTER TABLE parcel_mutations  ENABLE ROW LEVEL SECURITY;
ALTER TABLE field_inspections ENABLE ROW LEVEL SECURITY;

DO $do$
DECLARE
  t     text;
  cmd   text;
  body  text;
BEGIN
  FOREACH t IN ARRAY ARRAY['parcel_owners','parcel_mutations','field_inspections'] LOOP
    FOREACH cmd IN ARRAY ARRAY['SELECT','INSERT','UPDATE','DELETE'] LOOP
      EXECUTE format('DROP POLICY IF EXISTS tenant_%s_%I ON %I', lower(cmd), t, t);
    END LOOP;

    -- "The parent parcel is one this tenant can see." Nothing here re-states the tenant test itself:
    -- the subquery is subject to 0006's policy on parcels, so there is exactly one definition of
    -- tenancy in the database. Parenthesized because USING/WITH CHECK take an expression in brackets.
    body := format('(EXISTS (SELECT 1 FROM parcels p WHERE p.id = %I.parcel_id))', t);

    EXECUTE format('CREATE POLICY tenant_select_%I ON %I AS PERMISSIVE FOR SELECT TO dharohar_app USING %s', t, t, body);
    EXECUTE format('CREATE POLICY tenant_insert_%I ON %I AS PERMISSIVE FOR INSERT TO dharohar_app WITH CHECK %s', t, t, body);
    EXECUTE format('CREATE POLICY tenant_update_%I ON %I AS PERMISSIVE FOR UPDATE TO dharohar_app USING %s WITH CHECK %s', t, t, body, body);
    EXECUTE format('CREATE POLICY tenant_delete_%I ON %I AS PERMISSIVE FOR DELETE TO dharohar_app USING %s', t, t, body);
    RAISE NOTICE '[0009] % inherits parcels'' row-level security (4 policies, role dharohar_app)', t;
  END LOOP;
END
$do$;

-- ---- 4. Self-check: the policies really are as narrow as they look ----------
-- Asserting the shape here rather than trusting the loop above: a policy that silently ended up
-- AS RESTRICTIVE, or with no role, or WITH CHECK missing on INSERT, would change what tenants can
-- write and would be invisible until someone tried.
DO $do$
DECLARE
  bad text;
BEGIN
  SELECT string_agg(x, '; ') INTO bad FROM (
    SELECT tablename || '/' || policyname || ' permissive=' || permissive || ' roles=' || array_to_string(roles, ',')
      FROM pg_policies
     WHERE tablename IN ('parcel_owners','parcel_mutations','field_inspections')
       AND (permissive <> 'PERMISSIVE' OR roles <> ARRAY['dharohar_app']::name[])
    UNION ALL
    SELECT 'missing ' || c.cmd || ' policy on ' || t.t
      FROM (VALUES ('SELECT'),('INSERT'),('UPDATE'),('DELETE')) c(cmd)
     CROSS JOIN (VALUES ('parcel_owners'),('parcel_mutations'),('field_inspections')) t(t)
     WHERE NOT EXISTS (SELECT 1 FROM pg_policies p
                        WHERE p.tablename = t.t AND p.cmd = c.cmd
                          AND p.policyname = 'tenant_' || lower(c.cmd) || '_' || t.t)
    UNION ALL
    SELECT 'INSERT policy on ' || tablename || ' has no WITH CHECK'
      FROM pg_policies
     WHERE tablename IN ('parcel_owners','parcel_mutations','field_inspections')
       AND cmd = 'INSERT' AND with_check IS NULL
  ) s(x);
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION E'[TENANCY_POLICY_SHAPE_UNEXPECTED] %\n  Nothing was changed.', bad;
  END IF;
END
$do$;

DO $do$
BEGIN
  RAISE NOTICE '[0009] tables under row-level security: %',
    (SELECT string_agg(c.relname, ', ' ORDER BY c.relname) FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE c.relrowsecurity AND n.nspname = 'public');
END
$do$;


-- End of 0009. Rollback (drops these twelve policies and disables the security again) is
-- rollback-0009.sql, and it is refused if a policy this file did not create is present.
